  `MACD_macd` decimal(10,8) DEFAULT NULL,
  `last_RSI` decimal(5,2) DEFAULT NULL,
  `15mins_ST` bit(1) NOT NULL DEFAULT b'0',
  `30mins_ST` bit(1) NOT NULL DEFAULT b'0',
  `2hrs_ST` bit(1) NOT NULL DEFAULT b'0',
  `1d_ST` bit(1) NOT NULL DEFAULT b'0',
  `last_update_DateTime` datetime NOT NULL DEFAULT (now()),
