CREATE TABLE `order_report` (
  `s_no` bigint NOT NULL AUTO_INCREMENT,
  `order_seq_id` bigint NOT NULL,
  `symbol_name` varchar(20) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL,
  `signal_type` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8_general_ci DEFAULT NULL,
  `order_quantity` decimal(8,2) DEFAULT NULL,
  `buy_price` decimal(12,8) DEFAULT NULL,
  `buy_amount` decimal(12,4) DEFAULT NULL,
  `sell_price` decimal(12,8) DEFAULT NULL,
  `sell_amount` decimal(12,4) DEFAULT NULL,
  `profit_amount` decimal(8,2) DEFAULT NULL,
  `profit_percent` decimal(8,2) DEFAULT NULL,
  `username` varchar(50) CHARACTER SET utf8mb3 COLLATE utf8_general_ci NOT NULL,
  `order_date` datetime NOT NULL,
  `update_date` datetime DEFAULT NULL,
  `sell_reason` varchar(200) CHARACTER SET utf8mb3 COLLATE utf8_general_ci DEFAULT NULL,
  `commission_price` decimal(12,8) DEFAULT NULL,
  PRIMARY KEY (`s_no`)
) ENGINE=InnoDB AUTO_INCREMENT=736 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
