CREATE DEFINER=`root`@`localhost` PROCEDURE `user_recent_activity`(
username NVARCHAR(50),
fromDate NVARCHAR(50),
toDate NVARCHAR(50)
)
BEGIN
select cast(`Date` as Date) as 'date', side, activity, `type`, quantity, symbol, amount from (
select bcsd.order_date as 'Date', 'Buy' as side, concat('Bought ', replace(bcsn.symbol_full_name, '_', '')) as activity, bcsd.signal_type as 'type', FLOOR(bcsd.order_quantity) as quantity, bcsn.symbol_name as symbol, concat(bcsd.buy_amount, ' BUSD') as amount from `ant_cryptotradingbot`.`order_report`  as bcsd
inner join `ant_cryptotradingbot`.`crypto_symbols_name` as bcsn on bcsn.symbol_name = replace(bcsd.symbol_name, 'USDT', '')
where bcsd.username = username and bcsd.order_date >= fromDate and bcsd.order_date <= toDate
union all
select csd.update_date as 'Date', 'Sell' as side, concat('Sell ', replace(csn.symbol_full_name, '_', '')) as activity, csd.sell_reason as 'type', FLOOR(csd.order_quantity) as quantity, csn.symbol_name as symbol, concat(csd.sell_amount, ' BUSD') as amount from `ant_cryptotradingbot`.`order_report`  as csd
inner join `ant_cryptotradingbot`.`crypto_symbols_name` as csn on csn.symbol_name = replace(csd.symbol_name, 'USDT', '')
where csd.username = username and csd.update_date >= fromDate and csd.update_date <= toDate and csd.update_date is not null
order by `Date` desc) as cte;

END ;;
DELIMITER ;
